CREATE TABLE link_groups (id INTEGER PRIMARY KEY, send_key TEXT NOT NULL, url TEXT NOT NULL, system_number TEXT NOT NULL, created_by TEXT NOT NULL, created_at INTEGER NOT NULL, recipients INTEGER NOT NULL DEFAULT 0, clicked INTEGER NOT NULL DEFAULT 0, clicks INTEGER NOT NULL DEFAULT 0, auto_clicks INTEGER NOT NULL DEFAULT 0, last_click_at INTEGER, updated_at INTEGER NOT NULL, UNIQUE (send_key, url));
CREATE INDEX idx_link_groups_time ON link_groups(created_at, id);
ALTER TABLE links ADD COLUMN group_id INTEGER;
CREATE TABLE short_links (code TEXT PRIMARY KEY, url TEXT NOT NULL, title TEXT NOT NULL DEFAULT '', active INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0,1)), created_by TEXT NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, clicks INTEGER NOT NULL DEFAULT 0, auto_clicks INTEGER NOT NULL DEFAULT 0, last_click_at INTEGER) WITHOUT ROWID;
CREATE TABLE short_link_days (code TEXT NOT NULL, day TEXT NOT NULL, clicks INTEGER NOT NULL DEFAULT 0, auto_clicks INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (code, day)) WITHOUT ROWID;
INSERT INTO link_groups (send_key,url,system_number,created_by,created_at,recipients,clicked,clicks,auto_clicks,last_click_at,updated_at) SELECT l.send_id,l.url,l.system_number,COALESCE((SELECT s.email FROM sends s WHERE s.id=l.send_id),''),MIN(l.created_at),COUNT(DISTINCT l.peer_number),COUNT(DISTINCT CASE WHEN l.clicks>0 THEN l.peer_number END),SUM(l.clicks),SUM(l.auto_clicks),MAX(l.last_click_at),MIN(l.created_at) FROM links l GROUP BY l.send_id,l.url;
UPDATE links SET group_id=(SELECT g.id FROM link_groups g WHERE g.send_key=links.send_id AND g.url=links.url);
